-- 2) 651 Cultural Ambassador amount correction (description REPLACE)
UPDATE scholarships SET description = REPLACE(description, 'A separate Cultural Ambassador Scholarship of up to HK$50,000 a year goes to selected non-local students who help diversify the undergraduate community.', 'A separate Cultural Ambassador Scholarship — a renewable award of up to HK$60,000 a year for which eligible students are considered automatically — goes to selected non-local students who serve as cultural ambassadors with the Global Engagement Office, promoting PolyU to prospective students and parents.'), last_verified_at = '2026-10-30 08:00:00+05', last_updated_at = '2026-10-30 08:00:00+05', notes = COALESCE(notes, '') || ' BATCH 42 (2026-10-30): the Cultural Ambassador figure flagged by Pass 135 is corrected from up to HK$50,000 to a renewable award of up to HK$60,000 per year on the strength of the scheme''s own page (source 3190, fetched first-hand today), which also confirms that no application is required (eligible students are considered automatically) and that recipients work with the Global Engagement Office as cultural ambassadors; the description was updated accordingly. Entry-scholarship terms are unchanged.' WHERE id = 651 AND notes NOT LIKE '%BATCH 42%';

-- 3) NEW 1006 (PolyU STARS)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES
(1006, 'PolyU Special Talents Admission and Recognition Scheme (STARS) Scholarship for Non-Local Students', 'The Hong Kong Polytechnic University (PolyU)', 'Hong Kong SAR', 'Partial Tuition', 0, 'No separate scholarship application or closing date — apply to PolyU through the STARS admission route in eAdmission and you are considered automatically; the operative dates are the 2027 entry admission rounds (early round closes 17 November 2026, main round 11 February 2027, late applications to 14 May 2027 subject to places).', '["Bachelor"]', '["All Majors"]', NULL, NULL, false, true, 'The Special Talents Admission and Recognition Scheme (STARS) is PolyU''s alternative admission route for non-local undergraduates whose exceptional achievements in Sports, Arts and Culture, Leadership and Community Services, or STEM cannot be fully reflected in their academic results — and the STARS Scholarship rewards those talents with tiered tuition support. For 2027/28 (the tiers are published as subject to approval) there are six levels: Tier 1 pairs a renewable full-tuition scholarship with a renewable HK$60,000 annual allowance; Tier 2 pairs renewable full tuition with a HK$15,000 allowance; Tier 3 is renewable full tuition; Tier 4 is renewable half tuition; and Tiers 5 and 6 are one-off full- and half-tuition awards. The renewable tiers continue subject to meeting the university''s scholarship renewal conditions. There is no separate scholarship form: eligible applicants are considered automatically for the STARS Scholarship, so the task is the admission application itself in eAdmission. STARS sits next to PolyU''s academic entry scholarships (record 651) as the talent-based route — the strongest PolyU funding for a non-local student whose distinction lies outside examination grades.', 'Be a non-local undergraduate applicant with special talents in one of the four recognised areas — Sports, Arts and Culture, Leadership and Community Services, or STEM — whose exceptional achievements may not be fully reflected in academic results, and apply to PolyU through the STARS admission route for a full-time undergraduate programme. Eligible applicants are then considered for the scholarship automatically; there is no separate scholarship application. You must still meet PolyU''s undergraduate admission requirements, including the English language requirement for your qualification. The published 2027/28 tiers are subject to approval, and the renewable tiers continue only while the university''s scholarship renewal conditions are met — the detailed renewal conditions are not stated on the scholarship page.', 'https://www.polyu.edu.hk/study/ug/fees-and-scholarships/scholarships/non-local-stars-scholarship', '["All"]', 'Talent-based', 'Partial or full tuition (six tiers, up to renewable full tuition plus a HK$60,000 annual allowance)', NULL, NULL, NULL, NULL, 'No fixed IELTS score is published for this scholarship; applicants must meet PolyU''s undergraduate admission English language requirement for their qualification (check the official admissions page).', '["PolyU undergraduate admission application via eAdmission (STARS route; no separate scholarship form)","Academic transcripts and examination results","Details of achievements in your talent area (Sports, Arts and Culture, Leadership and Community Services, or STEM), provided within the admission application"]', 'https://www.polyu.edu.hk/study/ug/admissions/international-other-qualifications', NULL, '2027-02-11', 'automatic', NULL, NULL, '[]', 'annual', 'Late September (PolyU admission application opens; 23 September 2026 for 2027 entry)', 'Mid-February main admission round (11 February 2027 for 2027 entry; early round 17 November 2026)', 'open', '2026-10-30 08:00:00+05', '2026-10-30 08:00:00+05', 'verified', 10, 'https://www.polyu.edu.hk/study/ug/fees-and-scholarships/scholarships/non-local-stars-scholarship', 'NEW in Enrichment Batch 42 (2026-10-30), written from the first-hand read of PolyU''s official STARS Scholarship page for non-local students (source 3191 — six 2027/28 tiers published as subject to approval, automatic consideration, renewal subject to conditions), which surfaced during the Pass 135 Hong Kong cleanup of the sibling academic entry-scholarship record (651). deadline_date stores the operative main-round admission close for 2027 entry (11 February 2027) with deadline_type=automatic, mirroring the automatic-award convention of records 1002/1003; the 2027 admission-round dates were verified on PolyU pages on 2026-10-23 for record 651''s applicant stream and are stated with their provenance in the deadline narrative. Amount: multi-tier scheme, so award_amount is NULL with HKD/year/range and a 0 USD value (the tiers are tuition fractions — full/half tuition — rather than one cash figure). min_gpa/min_ielts NULL: STARS is a talent-based route with no published academic or English cutoff on the page read.', true, 72, NULL, 'HKD', 'year', 'range');

